def dbf(tau_i, t):
    if t < tau_i.D:
        return 0
    num_jobs = floor((t - tau_i.D) / tau_i.T) + 1
    return num_jobs * tau_i.C

def dbf_star(tau_i, t):
    if t < tau_i.D:
        return 0
    return ((t - tau_i.D) / tau_i.T + 1) * tau_i.C

def check_resource_augmentation(algorithm_A, task_set, M, rho):
    if is_feasible_optimally(task_set, M, speed=1):
        # If algorithm_A fails at speed 1, it must succeed at speed rho
        return algorithm_A.succeeds(task_set, M, speed=rho)
    return True # Trivial if not optimally feasible

def define_multi_analysis_vars(task_set_assigned_per_processor, tau_N_prime, D_N_prime, M_1_processors):
    total_C_on_M1 = 0
    for m in M_1_processors:
        total_C_on_M1 += sum(t.C for t in task_set_assigned_per_processor[m])

    if total_C_on_M1 == 0:
        return None, None, None

    beta_multi = tau_N_prime.C / total_C_on_M1

    sum_demand_part_M1 = 0
    for m in M_1_processors:
        for t_i in task_set_assigned_per_processor[m]:
            sum_demand_part_M1 += ((D_N_prime - t_i.D) / t_i.T) * t_i.C
    k_dagger_multi = sum_demand_part_M1 / total_C_on_M1

    k_multi = (len(M_1_processors) * D_N_prime - (1 + beta_multi) * total_C_on_M1) / total_C_on_M1

    return beta_multi, k_dagger_multi, k_multi
